
.range-line {
  color: var(--sys-lilac);
  font-size: 11px;
  margin-bottom: 4px;
  text-shadow: 0 0 6px rgba(181, 108, 255, 0.4);
}

.thought-row {
  background: var(--sys-panel);
  border: 1px solid rgba(181, 108, 255, 0.3);
  border-radius: 10px;
  padding: 6px 8px;
  margin-bottom: 4px;
}

.thought-name {
  display: block;
  font-weight: 700;
  color: var(--sys-violet);
  margin-bottom: 3px;
}

.thought-text {
  color: var(--sys-text);
  font-size: 12px;
  line-height: 1.6;
  word-break: break-word;
  text-shadow: 0 0 6px rgba(181, 108, 255, 0.2);
}
