
.points {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(90deg, rgba(255, 201, 77, 0.15), rgba(255, 45, 120, 0.08));
  border: 1px solid rgba(255, 201, 77, 0.5);
  border-radius: 10px;
  padding: 8px 12px;
}

.points-label {
  font-weight: 700;
  color: var(--sys-gold);
}

.points-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--sys-gold);
  text-shadow: 0 0 10px rgba(255, 201, 77, 0.7);
}

.shop-row {
  background: var(--sys-panel);
  border: 1px solid rgba(255, 95, 162, 0.3);
  border-radius: 10px;
  padding: 8px 10px;
  margin-bottom: 6px;
}

.shop-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 3px;
}

.shop-name {
  font-weight: 700;
  color: var(--sys-pink);
}

.shop-price {
  color: var(--sys-gold);
  font-weight: 700;
  font-size: 12px;
}

.shop-desc {
  color: var(--sys-text);
  font-size: 12px;
}

.shop-effect {
  color: var(--sys-green);
  font-size: 11px;
  margin-top: 2px;
}

.shop-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 4px;
}

.buy-btn {
  background: linear-gradient(90deg, var(--sys-pink-deep), var(--sys-violet));
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 3px 14px;
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: filter 0.15s;
}

.buy-btn:hover:not(:disabled) {
  filter: brightness(1.2);
}

.buy-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
