
.detail {
  padding-top: 6px;
}

.private-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.private-card {
  background: rgba(255, 45, 120, 0.06);
  border: 1px solid rgba(255, 95, 162, 0.25);
  border-radius: 8px;
  padding: 5px 7px;
}

.private-name {
  display: flex;
  align-items: center;
  font-weight: 700;
  color: var(--sys-pink);
  font-size: 13px;
  margin-bottom: 3px;
}

.part-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 6px;
  box-shadow: 0 0 6px rgba(255, 255, 255, 0.5);
}

.private-row {
  display: flex;
  gap: 8px;
  font-size: 13px;
  line-height: 1.6;
}

.private-k {
  flex-shrink: 0;
  color: var(--sys-text-dim);
  min-width: 2.5em;
}

.private-v {
  color: var(--sys-text);
  word-break: break-word;
}

.child-chip {
  margin: 1px 2px 1px 0;
  line-height: 1.8;
}

.cycle-note {
  color: var(--sys-text-dim);
  font-size: 12px;
}

.preg {
  margin-top: 6px;
  border: 1px solid rgba(181, 108, 255, 0.35);
  border-radius: 10px;
  background: rgba(181, 108, 255, 0.05);
  overflow: hidden;
}

.preg-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: transparent;
  border: none;
  color: var(--sys-lilac);
  font-family: inherit;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 1px;
  cursor: pointer;
  text-align: left;
}

.preg-title {
  white-space: nowrap;
}

.preg-summary {
  flex: 1;
  color: var(--sys-text-dim);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chevron {
  color: var(--sys-lilac);
  transition: transform 0.2s;
  flex-shrink: 0;
}

.chevron.open {
  transform: rotate(180deg);
}

.preg-body {
  padding: 6px 10px 8px;
  border-top: 1px dashed rgba(181, 108, 255, 0.3);
}
