
.xianer {
  padding: 10px 14px;
  border-bottom: 1px dashed rgba(255, 95, 162, 0.4);
  background: rgba(255, 45, 120, 0.06);
}

.xianer-head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.xianer-avatar {
  font-size: 16px;
  filter: drop-shadow(0 0 6px rgba(181, 108, 255, 0.8));
}

.xianer-name {
  font-weight: 700;
  color: var(--sys-lilac);
  text-shadow: 0 0 8px rgba(181, 108, 255, 0.6);
}

.xianer-tag {
  font-size: 11px;
  color: var(--sys-pink);
  border: 1px solid var(--sys-pink);
  border-radius: 4px;
  padding: 0 5px;
}

.xianer-bubble {
  position: relative;
  background: var(--sys-panel);
  border: 1px solid rgba(255, 95, 162, 0.35);
  border-radius: 4px 12px 12px 12px;
  padding: 8px 10px;
  color: var(--sys-text);
  font-size: 13px;
  line-height: 1.6;
  word-break: break-word;
}

/* 气泡小尾巴 */
.xianer-bubble::before {
  content: '';
  position: absolute;
  left: -7px;
  top: 14px;
  border-style: solid;
  border-width: 6px 8px 6px 0;
  border-color: transparent var(--sys-panel) transparent transparent;
  filter: drop-shadow(-1px 0 0 rgba(255, 95, 162, 0.35));
}
