
.item-row {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--sys-panel);
  border: 1px solid rgba(181, 108, 255, 0.25);
  border-radius: 8px;
  padding: 6px 8px;
  margin-bottom: 4px;
}

.item-name {
  font-weight: 700;
  color: var(--sys-lilac);
  white-space: nowrap;
}

.item-desc {
  flex: 1;
  color: var(--sys-text-dim);
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.item-count {
  background: var(--sys-panel-2);
  color: var(--sys-gold);
  border: 1px solid rgba(255, 201, 77, 0.4);
  padding: 0 6px;
  border-radius: 4px;
  font-size: 11px;
  white-space: nowrap;
}

.use-btn {
  background: var(--sys-pink-deep);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 2px 10px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: filter 0.15s;
}

.use-btn:hover {
  filter: brightness(1.2);
}

.trophy {
  margin-top: 6px;
  border: 1px solid rgba(255, 45, 120, 0.35);
  border-radius: 10px;
  background: rgba(255, 45, 120, 0.05);
}

.trophy-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  background: transparent;
  border: none;
  color: var(--sys-pink);
  font-family: inherit;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
}

.trophy-head span:first-child {
  flex: 1;
  text-align: left;
}

.trophy-count {
  background: var(--sys-pink-deep);
  color: #fff;
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 999px;
}

.chevron {
  color: var(--sys-pink);
  transition: transform 0.2s;
}

.chevron.open {
  transform: rotate(180deg);
}

.trophy-body {
  padding: 0 10px 10px;
  border-top: 1px dashed rgba(255, 45, 120, 0.3);
}

.trophy-row {
  padding: 6px 0;
  border-bottom: 1px solid rgba(181, 108, 255, 0.15);
}

.trophy-row:last-child {
  border-bottom: none;
}

.trophy-name {
  font-weight: 700;
  color: var(--sys-pink);
  font-size: 12px;
}

.trophy-desc {
  color: var(--sys-text);
  font-size: 12px;
  margin-top: 2px;
  word-break: break-word;
}

.trophy-meta {
  color: var(--sys-text-dim);
  font-size: 11px;
  margin-top: 4px;
}

.meta-line {
  line-height: 1.7;
}
